import{z as o,x as s,o as A,c as p,q as t,j as r,D as l,d as a,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"投机解码收束","description":"","frontmatter":{"title":"投机解码收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-map.md","filePath":"llm/spec-map.md","lastUpdated":1791063341000}'),m={name:"llm/spec-map.md"};function d(F,E,D,c,h,g){const B=s("Mermaid");return A(),p("div",null,[E[2]||(E[2]=t('<h1 id="投机解码收束" tabindex="-1">投机解码收束 <a class="header-anchor" href="#投机解码收束" aria-label="Permalink to &quot;投机解码收束&quot;">​</a></h1><div class="epigraph"><p>收束不是把十一课再讲一遍，而是回答一个问题：明天上线，先做什么、后做什么、什么永远不碰。</p><footer>—— 据 Leviathan et al., ICML 2023 与 Miao et al., ASPLOS 2024 的系统口径，按本课程整理</footer></div><p><a href="/llm/spec-experiment-method">上一课</a>把测量钉成了方法。至此零件齐了：草稿供给侧的谱系、系统里的三处交互、理论与训练的上下游——本课把它们装配成一张地图和一张决策单。上游是<a href="/llm/kv-map">KV 管理</a>与<a href="/llm/ak-speculative-interaction">注意力内核</a>给投机备好的缓存与核，下游是测量与成本给投机判的分。本课程回答中间这一层：串行步怎么省。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投机解码的决策散在四个层面：要不要开（余量与成本比）、草稿用谁（谱系五族）、形状怎么调（\\(\\gamma\\) 与树宽）、怎么验收（口径与质量）。各自局部最优会互相拆台：在错误的批量上选草稿，选出的冠军上线垫底；在未量化的栈上调的树宽，量化部署后白调；为了报表演眼里的加速比放宽接受规则，正确性悄悄出局。没有全局顺序，团队最常见的两条弯路是：跳过测量直接抄论文数字立项，以及在带宽墙尚未确认时先堆树宽。收束要给的是这张先后表。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>决策单</strong>，按「先看余量、再选草稿、后调形状、全程钉口径」排序：</p><ol><li><strong>确认余量</strong>：测 decode 的算术强度与批量分布；带宽墙下校验近免费，算力屋顶下先考虑缩批或关投机。</li><li><strong>零权重草稿先行</strong>：复制与结构化流量用 n-gram/检索草稿，不占内存不训模型，先赚最便宜的一截。</li><li><strong>学习型草稿主攻</strong>：闭源自投机头或特征级草稿，按能否改目标权重定介入深度；数据对齐服务流量分桶。</li><li><strong>形状随账走</strong>：\\(\\gamma\\) 与树宽按桶级 \\(\\alpha\\) 与实测 \\(c_{\\mathrm{tgt}}\\) 调，批量升则收树，低 \\(\\alpha\\) 桶降为 \\(\\gamma=0\\)。</li><li><strong>联评量化</strong>：在部署的精度档上重测 \\(\\alpha\\) 与成本比，声明「无损相对部署的 \\(p\\)」。</li><li><strong>验收钉口径</strong>：四级数字各报各级，加速比交代分母，有偏变体过质量关。</li></ol><p>永不碰的三件事：为长度放宽接受规则而不声明（改分布）、树掩码错成因果（正确性事故）、拿 batch=1 贪心峰值当服务数字（口径注水）。</p>',9)),(A(),r(i,null,{default:l(()=>[n(B,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22%E7%A1%AE%E8%AE%A4%E4%BD%99%E9%87%8F%EF%BC%9Aroofline%20%E4%B8%8E%E6%89%B9%E9%87%8F%22%5D%20--%3E%20M2%5B%22%E9%9B%B6%E6%9D%83%E9%87%8D%E8%8D%89%E7%A8%BF%EF%BC%9An-gram%20%2F%20%E6%A3%80%E7%B4%A2%22%5D%0A%20%20M2%20--%3E%20M3%5B%22%E5%AD%A6%E4%B9%A0%E5%9E%8B%E8%8D%89%E7%A8%BF%EF%BC%9A%E8%87%AA%E6%8A%95%E6%9C%BA%20%2F%20%E7%89%B9%E5%BE%81%E7%BA%A7%22%5D%0A%20%20M3%20--%3E%20M4%5B%22%E5%BD%A2%E7%8A%B6%EF%BC%9A%CE%B3%20%E4%B8%8E%E6%A0%91%E5%AE%BD%E6%8C%89%E6%A1%B6%E8%B4%A6%E8%B0%83%22%5D%0A%20%20M4%20--%3E%20M5%5B%22%E9%87%8F%E5%8C%96%E8%81%94%E8%AF%84%EF%BC%9A%E9%83%A8%E7%BD%B2%E6%A1%A3%E4%B8%8A%E9%87%8D%E6%B5%8B%22%5D%0A%20%20M5%20--%3E%20M6%5B%22%E9%AA%8C%E6%94%B6%EF%BC%9A%E5%9B%9B%E7%BA%A7%E5%8F%A3%E5%BE%84%20%2B%20%E8%B4%A8%E9%87%8F%22%5D%0A%20%20M1%20--%3E%20TH%5B%22%E7%90%86%E8%AE%BA%EF%BC%9A%CE%B1%20%3D%201%20%E2%88%92%20TV(p%2Cq)%22%5D%0A%20%20TH%20--%3E%20M4%0A%20%20M4%20--%3E%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E4%BA%A4%E4%BA%92%EF%BC%9A%E6%89%B9%20%2F%20KV%20%2F%20%E5%86%85%E6%A0%B8%20%2F%20%E7%AB%AF%E4%BE%A7%22%5D%0A%20%20SYS%20--%3E%20M6%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("地图的骨架是三个不变量。"),e("strong",null,"不变量一"),a("：收益公式——每轮期望前进除以一轮成本比——从"),e("a",{href:"/llm/speculative-decoding"},"原理课"),a("到收束没有变过，谱系改分子（\\(\\alpha\\)、\\(\\tau\\)），系统交互改分母（\\(c_q/c_p\\)），理论与训练上游供给分子，测量验收保证两个因子没被量错。"),e("strong",null,"不变量二"),a("：无损性由接受规则对部署的 \\(p\\) 兑现，任何环节（树掩码、提交协议、采样器对齐）破了它，加速都是错的。"),e("strong",null,"不变量三"),a("：余量唯一——批量、量化、投机共抢同一份「算不满」，配置的全部艺术在分配这份余量，而不在堆任何一个单项。三条不变量定了，参数怎么换代，决策单的顺序不动。")],-1)),(A(),r(i,null,{default:l(()=>[n(B,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%94%B6%E7%9B%8A%20%3D%20%E6%AF%8F%E8%BD%AE%E6%9C%9F%E6%9C%9B%E5%89%8D%E8%BF%9B%20%C3%B7%20%E4%B8%80%E8%BD%AE%E6%88%90%E6%9C%AC%E6%AF%94%22%5D%20--%3E%20NU%5B%22%E5%88%86%E5%AD%90%3A%20%CE%B1%20%E4%B8%8E%20%CF%84%22%5D%0A%20%20F%20--%3E%20DE%5B%22%E5%88%86%E6%AF%8D%3A%20%E6%88%90%E6%9C%AC%E6%AF%94%20c_q%20%2F%20c_p%22%5D%0A%20%20NU%20--%3E%20G1%5B%22%E8%B0%B1%E7%B3%BB%E4%BA%94%E6%97%8F%3A%20%E6%94%B9%E5%88%86%E5%AD%90%22%5D%0A%20%20NU%20--%3E%20G2%5B%22%E7%90%86%E8%AE%BA%E4%B8%8E%E8%AE%AD%E7%BB%83%3A%20%E4%BE%9B%E7%BB%99%E5%88%86%E5%AD%90%22%5D%0A%20%20DE%20--%3E%20G3%5B%22%E6%89%B9%E9%87%8F%20%2F%20%E9%87%8F%E5%8C%96%20%2F%20%E7%AB%AF%E4%BE%A7%3A%20%E6%94%B9%E5%88%86%E6%AF%8D%22%5D%0A%20%20F%20--%3E%20LO%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%E4%BA%8C%3A%20%E6%97%A0%E6%8D%9F%E7%9B%B8%E5%AF%B9%E9%83%A8%E7%BD%B2%E7%9A%84%20p%22%5D%0A%20%20LO%20--%3E%20W%5B%22%E6%A0%91%E6%8E%A9%E7%A0%81%E6%88%96%E6%8F%90%E4%BA%A4%E5%8D%8F%E8%AE%AE%E4%B8%80%E7%A0%B4%2C%20%E5%8A%A0%E9%80%9F%E5%8D%B3%E9%94%99%22%5D%0A%20%20F%20--%3E%20YU%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%E4%B8%89%3A%20%E4%BD%99%E9%87%8F%E5%94%AF%E4%B8%80%2C%20%E4%B8%89%E6%96%B9%E5%85%B1%E6%8A%A2%22%5D%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">一张自检表：如果只做三件事——先测批量与 roofline 确认余量，再给复制型流量上零权重草稿，然后在主力流量上挂一个特征级草稿并按桶调 \\(\\gamma\\)。多数服务在第三步就已拿到大半收益，后面的每一步都要求先证明前面拿不出来了。</span></p><p><span class="marginnote">术语翻译：「无损相对部署的 \\(p\\)」是说保分布的基准是『实际在跑的那份模型』——如果线上是量化版，无损就对量化版成立，不担保与原版全精度逐 token 相同。看到「无损」两个字，永远追问一句：相对谁？</span></p><p><span class="marginnote">直觉类比：把 GPU decode 的「算不满」想成一块蛋糕。批量切一块，量化切一块，投机再来切——三者的收益此消彼长，因为蛋糕只有一块。所以「全都要」不是配置，是抢蛋糕。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张图有时效。草稿谱系还在加代（训练期多步对齐、更大的草稿缩放曲线），硬件代际移动 roofline 的交点，端侧与集群的成本结构各自演化——参数会换，三条不变量与决策单的顺序是本课程打算留下的部分。边界之外由相邻课程接棒：调度的成员边界与优先级归服务调度，缓存峰值归 <a href="/llm/kv-map">KV 管理</a>，校验的核归<a href="/llm/ak-speculative-interaction">注意力内核</a>。投机解码交付的始终是同一件事：把串行的步数换成并行的校验，并让每一分换来的加速都在正确的口径下被数出来。</p><p><span class="marginnote">常见误区：把决策单当成一次跑完就归档的项目。换模型、换精度档、流量结构变化后，都要从「确认余量」起按顺序重走一遍——旧账上的冠军草稿，在新余量下可能连及格线都不到。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单六步：确认余量 → 零权重草稿 → 学习型草稿 → 形状按桶账 → 量化联评 → 四级口径验收。</li><li>三条不变量：收益公式、无损相对部署的 \\(p\\)、余量唯一；参数换代，顺序不动。</li><li>永不碰：不声明地放宽接受规则、树掩码错成因果、拿单请求贪心峰值当服务数字。</li><li>谱系五族按成本排：n-gram/检索、自投机头、特征级草稿、独立小模型、云校验分工。</li><li>收益每一分都在「接受长度 × 成本比」的账上兑现；量错口径等于没赚。</li><li>出处：Leviathan et al., <em>Fast Inference via Speculative Decoding</em>, ICML 2023；Chen et al., 2023；Cai et al., Medusa, ICML 2024；Li et al., EAGLE 系列， 2024–2025；Miao et al., SpecInfer, ASPLOS 2024。</li></ul>',8))])}const u=o(m,[["render",d]]);export{f as __pageData,u as default};
